//! Host-to-plugin attachment through a library's exported symbols.
//!
//! Each function looks up one optional symbol that `export_plugin!` generates
//! and shares one piece of host state (manifest, world runtimes, profiler,
//! event bus) with the library. They run before the plugin constructor, from
//! `loading.rs`. A library built before a symbol existed simply returns `None`.

use crate::PermanentLibrary;
use plugin_editor_api::*;

/// The manifest `library` exports through `_plugin_manifest` (generated by
/// `export_plugin!`). `None` when it exports none (built before manifests) or
/// building it panicked.
pub fn read_manifest(library: &PermanentLibrary) -> Option<PluginManifest> {
    // SAFETY: the symbol is `plugin_editor_api::PluginManifestFn` in every
    // library exporting it; the library is never unloaded.
    let manifest: libloading::Symbol<plugin_editor_api::PluginManifestFn> =
        unsafe { library.get(b"_plugin_manifest") }.ok()?;
    manifest()
}

/// Attach `library`'s world crates to this process's world runtimes through
/// its [`ATTACH_SYMBOL`](pulsar_world_registry::runtime::ATTACH_SYMBOL) entry
/// point (exported by `export_plugin!`). `None` when the library does not
/// export it (built before #1083); `Some(false)` when it refused them.
pub fn attach_world_runtime(library: &PermanentLibrary) -> Option<bool> {
    // SAFETY: the symbol is `pulsar_world_registry::runtime::AttachFn` in
    // every library exporting it (generated by `export_world_runtime_attach!`).
    let attach: libloading::Symbol<pulsar_world_registry::runtime::AttachFn> =
        unsafe { library.get(pulsar_world_registry::runtime::ATTACH_SYMBOL.as_bytes()) }.ok()?;
    let host: *const pulsar_world_registry::runtime::WorldRuntimes =
        pulsar_world_registry::runtime::host();
    // SAFETY: `host` is this process's runtimes, which live for the process;
    // plugins are never unloaded.
    Some(unsafe { attach(host.cast()) })
}

/// Share this process's profiler with `library` through its
/// [`ATTACH_SYMBOL`](profiling::scope::ATTACH_SYMBOL) entry point. `None` when it
/// does not export it; `Some(false)` when it refused (different layout).
pub fn attach_profiler(library: &PermanentLibrary) -> Option<bool> {
    let attach: libloading::Symbol<unsafe extern "C" fn(*const std::ffi::c_void) -> bool> =
        unsafe { library.get(profiling::scope::ATTACH_SYMBOL.as_bytes()) }.ok()?;
    // Leaked: plugins are never unloaded, so the handle must outlive them.
    let handle: &'static profiling::scope::HostProfiler =
        Box::leak(Box::new(profiling::scope::host_handle()));
    // SAFETY: `handle` is this process's profiler handle, valid for the process.
    Some(unsafe { attach((handle as *const profiling::scope::HostProfiler).cast()) })
}

/// Hand `library` the host's Gamma event bus through its
/// [`ATTACH_SYMBOL`](pulsar_events::host::ATTACH_SYMBOL) entry point
/// (exported by `export_plugin!`). Returns its `ATTACH_*` status, or `None`
/// when the library does not export it (built before #930) or this process
/// cannot export a bus.
pub fn attach_event_bus(library: &PermanentLibrary) -> Option<u32> {
    // SAFETY: the symbol is `pulsar_events::host::AttachFn` in every library
    // exporting it (generated by `export_host_bus_attach!`).
    let attach: libloading::Symbol<pulsar_events::host::AttachFn> =
        unsafe { library.get(pulsar_events::host::ATTACH_SYMBOL.as_bytes()) }.ok()?;
    let raw = pulsar_events::host::export_host_bus()?;
    // SAFETY: `raw` is a fresh export of this process's host bus, which
    // lives as long as the process; plugins are never unloaded.
    Some(unsafe { attach(raw) })
}
